 teaching=['curriculum/v5/exercises/X-T15-002.md','labs/b02_followthrough/sort/CONTRACTS.md','assessor/b02_followthrough/sort/ANALYSIS.md'];implementation=['assessor/b02_followthrough/sort/sort.c','labs/b02_followthrough/sort/sort.h','labs/b02_followthrough/sort/tests.c','labs/b02_followthrough/sort/target.c','tools/verify_b02_sort.py','assessor/b02_depth/depth.c'];reports=[REPORT,TARGET,EXPORT]
 dims=dict(teaching=dict(state='complete',evidence=teaching),implementation=dict(state='complete',evidence=implementation),author_validation=dict(state='passed',evidence=reports+[BASE+'/sort_readiness.json']),external_review=dict(state='not-run',evidence=[]),independent_learner=dict(state='not-assessed',evidence=[]),physical_observation=dict(state='not-run',evidence=['labs/b02_followthrough/sort/CONTRACTS.md']))
 rows=[dict(id=i,author_readiness='ready-bounded',demonstration=c,teaching=teaching,implementation=implementation,validation=reports,external_review='not-run',independent_learner='not-assessed',physical_observation='not-run') for i,c in claims.items()]
 inputs={**d['input_sha256'],**t['input_sha256'],**e['input_sha256']}
 for p in teaching+implementation+reports+[BASE+'/sort_resources.json',BASE+'/sort_research_gate.json','tools/check_b02_sort.py','tools/register_b02_sort.py','tools/build_b02_sort_readiness.py','tools/check_replicated_replay_depth.py']:inputs[p]=sha(ROOT/p)
 ready=BASE+'/sort_readiness.json';dump(ROOT/ready,dict(schema_version=1,criteria=rows,input_sha256=inputs,current_reports={r:sha(ROOT/r) for r in reports},limits=['Only these four exact original IDs and their specific immediate/changed tasks.','Finite host and emulator observations; no arbitrary-implementation proof, physical observation, independent reviewer or learner result.','Exact published C17 and C23 remain inaccessible; N1570 is a C11 draft.']))
